/**
 * Markdown show-notes → sanitized HTML for microfeed `content_html`
 * (design D6.1; vendored-source contract: microfeed stores and re-emits
 * `content_html` verbatim — JSON Feed, RSS `content:encoded`, and the theme
 * template `{{{content_html}}}` unescaped-insert — and derives `content_text`
 * by stripping tags, so the field must be HTML, never markdown).
 *
 * The plugin's own show-notes dialect is closed (generated by the workflow
 * show-notes step): `#/##/###` headings, `[text](https://…)` links, `**bold**`,
 * paragraphs. Everything else is escaped text — sanitize-by-construction: the
 * input is escaped first, and only the tags this module emits reach the API.
 */

import { type Doc, splitSentences } from '@gobing-ai/kk-core';
import {
    type PlanItem,
    type PodcastSeoConfig,
    SEO_DEFAULTS,
    showNotesSummaryParagraph,
    type TimelineStyle,
    warn,
} from './seo';
import { CARDS_STYLE } from './show-notes-brief';

/** Escapes text content and attribute values (`&`, `<`, `>`, `"`). */
export function escapeHtml(value: string): string {
    return value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
}

function renderInline(escaped: string): string {
    let out = '';
    let rest = escaped;
    for (;;) {
        const match = rest.match(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/);
        if (!match || match.index === undefined) break;
        out += `${rest.slice(0, match.index)}<a href="${match[2]}" target="_blank" rel="noopener">${match[1]}</a>`;
        rest = rest.slice(match.index + match[0].length);
    }
    return (out + rest).replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
}

/**
 * Normalizes text for title↔transcription matching: lowercase, strip everything
 * that is not a CJK char, letter, or digit. ASR drops punctuation and case, and the
 * intro segment enumerates every title, so matching must be punctuation-blind and
 * monotonic (each item searches forward from the previous match).
 */
function normalizeForMatch(text: string): string {
    return text.toLowerCase().replace(/[^\p{Script=Han}\p{L}\p{N}]+/gu, '');
}

/** `m:ss` audio offset, or `--:--` when unknown. */
export function formatOffset(seconds: number): string {
    if (!Number.isFinite(seconds) || seconds < 0) return '--:--';
    const m = Math.floor(seconds / 60);
    const s = Math.round(seconds % 60);
    return s === 60 ? `${m + 1}:00` : `${m}:${String(s).padStart(2, '0')}`;
}

/**
 * Per-item audio offsets (seconds) from the generated segments. Exact mode: walk
 * segments after the intro (index 0), matching each item title inside a segment
 * transcription, monotonic forward. Proportional fallback (any title unmatched or no
 * segments): distribute total duration by body length — monotonic and close enough
 * for jump navigation. `ponytail`: no word-level alignment; segment starts are
 * accurate to one segment (~10–30s), fine for chapter jumps.
 */
export function computeAudioOffsets(
    docs: Doc[],
    segments: Array<{ duration?: number; transcription?: string }> | undefined,
): number[] {
    const fallback = (): number[] => {
        const chars = docs.map((d) => Math.max((d.body ?? '').trim().length, 1));
        const total = chars.reduce((a, b) => a + b, 0);
        const sumDuration = (segments ?? []).reduce((a, s) => a + (s.duration ?? 0), 0);
        let acc = 0;
        return chars.map((c) => {
            const at = acc;
            acc += (c / total) * sumDuration;
            return at;
        });
    };
    if (!segments || segments.length < 2) return fallback();
    const starts: number[] = [];
    let elapsed = 0;
    const marks = segments.map((s) => {
        const at = elapsed;
        elapsed += s.duration ?? 0;
        return { at, text: normalizeForMatch(s.transcription ?? '') };
    });
    let cursor = 1; // segment 0 is the intro, which recites every title
    for (const d of docs) {
        const title = normalizeForMatch(d.title ?? '');
        const needle = title.slice(0, 12);
        const hit = needle.length >= 4 ? marks.findIndex((m, i) => i >= cursor && m.text.includes(needle)) : -1;
        if (hit >= 0) {
            starts.push(marks[hit]?.at ?? 0);
            cursor = hit + 1;
        } else {
            starts.push(Number.NaN); // any miss degrades the whole run to proportional
        }
    }
    if (starts.some((v) => !Number.isFinite(v))) return fallback();
    return starts;
}

const isHttpUrl = (u: string): boolean => /^https?:\/\//i.test(u.trim());

/** The exact `<style>` block {@link renderTimelineHtml} emits; reused by the marker validator. */
const TIMELINE_STYLE = `<style>
.kk-tl{margin:1em 0}
.kk-tl-row{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid rgba(128,128,128,.25)}
.kk-tl-t{flex:0 0 56px;font-variant-numeric:tabular-nums;font-weight:700;color:#0969da}
.kk-tl-body{flex:1;min-width:0}
.kk-tl-title{font-weight:600}
.kk-tl-brief{margin:4px 0 0;color:#666;font-size:.95em}
</style>`;

/**
 * Tags {@link renderTimelineHtml} can emit: `div`/`p`/`a` carrying only the exact class, href,
 * target, and rel attributes it produces. Anything else inside a marker block is attacker-supplied.
 */
const TIMELINE_TAG =
    /^<\/?(?:div|p|a)(?:\s+(?:class="kk-tl(?:-[a-z]+)?"|href="https?:\/\/[^"<>\s]*"|target="_blank"|rel="noopener"))*\s*>$/;

/**
 * A marker block is trusted only if it is markup {@link renderTimelineHtml} could have produced.
 * The markers are a legitimate cross-process channel (see {@link renderShowNotesHtml}), so the
 * block is validated rather than stripped: a comment or `<style` inside it is an injection attempt,
 * and any leftover stray `<` means the block is not well-formed generator output.
 */
function isGeneratedTimeline(block: string): boolean {
    const rest = block.replace(TIMELINE_STYLE, '');
    if (rest.includes('<style') || rest.includes('<!--')) return false;
    return (rest.match(/<[^>]*>/g) ?? []).every((tag) => TIMELINE_TAG.test(tag)) && !/<(?![^>]*>)/.test(rest);
}

/**
 * Brief-mode timeline block: two-column HTML (offset left, title + briefing right),
 * marked `<!--kk:timeline-->` so {@link renderShowNotesHtml} passes it through
 * verbatim — everything inside is built here from escaped doc values, never user
 * input. `ponytail`: no JS — timestamp deep-linking depends on the theme's player
 * API; add when microfeed exposes one.
 */
function renderTimelineHtml(docs: Doc[], offsets: number[], articleUrl: string, style: TimelineStyle): string {
    const rows = docs
        .map((d, i) => {
            const title = escapeHtml(d.title ?? `条目 ${i + 1}`);
            const brief = escapeHtml(itemBrief(d));
            const at = formatOffset(offsets[i] ?? Number.NaN);
            // A `sourceUri` that is not http(s) (e.g. `javascript:`) must not become a live href;
            // escaping alone does not neutralise a scheme, so the link is dropped instead (R2).
            const link =
                d.sourceUri && isHttpUrl(d.sourceUri)
                    ? ` <a href="${escapeHtml(d.sourceUri)}" target="_blank" rel="noopener">来源</a>`
                    : '';
            return `
    <div class="kk-tl-row"><div class="kk-tl-t">${at}</div><div class="kk-tl-body"><div class="kk-tl-title">${i + 1}. ${title}${link}</div><p class="kk-tl-brief">${brief}</p></div></div>`;
        })
        .join('');
    const articleTail = isHttpUrl(articleUrl)
        ? `<p>完整图文版：<a href="${escapeHtml(articleUrl)}" target="_blank" rel="noopener">${escapeHtml('本期完整文章')}</a></p>`
        : `<p>${escapeHtml('本期完整文章')}</p>`;
    const styleBlock = style === 'omit' ? '' : `${TIMELINE_STYLE}\n`;
    // `after` (default) keeps the style inside the markers but after the list, so content_text
    // does not open on CSS. `before` is the pre-D9 position, for a byte-identical legacy render.
    const before = style === 'before' ? styleBlock : '';
    const after = style === 'after' ? styleBlock : '';
    return `<!--kk:timeline-->
${before}<div class="kk-tl">${rows}
</div>
${after}${articleTail}
<!--/kk:timeline-->`;
}

/**
 * 0386 R1 — the card-region counterpart of {@link isGeneratedTimeline}: a `<!--kk:cards-->` block is
 * trusted only if it is markup {@link renderCardsRegion} (show-notes-brief.ts) could have produced.
 * The card region is the only place an `<img>` legitimately appears in show notes, so its grammar is
 * pinned here rather than widening the timeline grammar.
 */
const CARDS_TAG =
    /^<\/?(?:div|figure|figcaption|span|p|img)(?:\s+(?:class="kk-cards"|class="kk-card"|class="kk-card-n"|src="https?:\/\/[^"<>\s]*"|alt="[^"<>]*"|loading="lazy"))*\s*\/?>$/;

function isGeneratedCards(block: string): boolean {
    const rest = block.replace(CARDS_STYLE, '');
    if (rest.includes('<style') || rest.includes('<!--') || rest.includes('<script')) return false;
    return (rest.match(/<[^>]*>/g) ?? []).every((tag) => CARDS_TAG.test(tag)) && !/<(?![^>]*>)/.test(rest);
}

/**
 * Renders show-notes markdown to sanitized HTML.
 * The leading `# ` heading is dropped: the episode `title` is rendered
 * separately by the page theme, so keeping it would duplicate the H1.
 * Input that already looks like HTML (`format: 'html'`) must be passed
 * through untouched by the caller, not here.
 */
export function renderShowNotesHtml(markdown: string): string {
    const blocks: string[] = [];
    const timeline: string[] = [];
    const cards: string[] = [];
    let inTimeline = false;
    let inCards = false;
    let paragraph: string[] = [];

    const flush = () => {
        if (paragraph.length > 0) {
            blocks.push(`<p>${renderInline(escapeHtml(paragraph.join(' ')))}</p>`);
            paragraph = [];
        }
    };

    // Escape every buffered timeline line through the normal paragraph path. Used when the block
    // fails {@link isGeneratedTimeline} and for a marker that is never closed.
    const escapeBufferedTimeline = () => {
        for (const l of timeline) {
            const t = l.trim();
            if (t.length > 0) paragraph.push(t);
        }
        timeline.length = 0;
        flush();
    };

    for (const rawLine of markdown.split('\n')) {
        const line = rawLine.trim();
        if (line === '<!--kk:timeline-->') {
            flush();
            inTimeline = true;
            continue;
        }
        if (line === '<!--kk:cards-->') {
            flush();
            inCards = true;
            continue;
        }
        if (inCards) {
            if (line === '<!--/kk:cards-->') {
                inCards = false;
                // Same trust rule as the timeline markers: pass a generator-shaped card block
                // through, escape anything else line by line (R2: never widen the HTML surface).
                if (isGeneratedCards(cards.join('\n'))) {
                    blocks.push(cards.join('\n'));
                } else {
                    for (const l of cards) {
                        const t = l.trim();
                        if (t.length > 0) paragraph.push(t);
                    }
                    flush();
                }
                cards.length = 0;
                continue;
            }
            cards.push(rawLine);
            continue;
        }
        if (inTimeline) {
            if (line === '<!--/kk:timeline-->') {
                inTimeline = false;
                // The marker is a legitimate cross-process channel: renderShowNotesMarkdown writes
                // the timeline into markdown, and that markdown later arrives as metadata.showNotes.
                // Stripping the markers would break the feature, so the block is validated against
                // the generator's own grammar instead — anything renderTimelineHtml could not have
                // produced is escaped line by line rather than passed through (R2).
                if (isGeneratedTimeline(timeline.join('\n'))) {
                    blocks.push(timeline.join('\n'));
                    timeline.length = 0;
                } else {
                    escapeBufferedTimeline();
                }
                continue;
            }
            timeline.push(rawLine);
            continue;
        }
        if (line.length === 0) {
            flush();
            continue;
        }
        const heading = line.match(/^(#{1,3})\s+(.*)$/);
        if (heading) {
            flush();
            const tag = heading[1]?.length === 1 ? 'h1' : heading[1]?.length === 2 ? 'h2' : 'h3';
            if (tag === 'h1' && blocks.length === 0 && paragraph.length === 0) {
                continue; // drop the duplicate title heading
            }
            blocks.push(`<${tag}>${renderInline(escapeHtml(heading[2] ?? ''))}</${tag}>`);
            continue;
        }
        paragraph.push(line);
    }
    flush();
    // An unclosed marker never reaches the closing branch above — escape whatever it buffered.
    if (timeline.length > 0) escapeBufferedTimeline();
    if (cards.length > 0) {
        for (const l of cards) {
            const t = l.trim();
            if (t.length > 0) paragraph.push(t);
        }
        cards.length = 0;
        flush();
    }
    return blocks.join('\n');
}

/**
 * Options for {@link renderShowNotesMarkdown} — the workflow show-notes step's
 * inputs (`title` = the effective episode title, `vars.title || article.title`
 * at the call site; `runDate` = the `YYYY-MM-DD` slug prefix).
 */
export interface ShowNotesRenderOptions {
    /** Episode heading, article-link text, and article-URL slug source. */
    title: string;
    /** Run date prefixing the article URL slug. */
    runDate: string;
    /** Article base URL; defaults to the production site (surfing.salty.vip). */
    articleBaseUrl?: string;
    /**
     * Brief/timeline mode (task 0118): per-item 1–2-sentence briefing + `HH:MM`
     * timestamp + per-item article link. When no surfdash article path is
     * available the render degrades to the legacy full-body layout — never
     * throws, never invents a URL.
     */
    briefMode?: boolean;
    /**
     * Absolute surfdash `metadata.postPath` from the publish result
     * (`content/posts/articles/<locale>/<slug>/index.md`); the article URL is
     * derived O(1) from its slug+locale — authoritative over the title/runDate
     * slug construction, which stays the fallback.
     */
    articlePostPath?: string;
    /**
     * Closing line appended verbatim in both layouts — the caller's production disclosure
     * (task 0189 R1: AI-voice note in episode metadata). Absent ⇒ no footer, byte-stable render.
     */
    footerNote?: string;
    /**
     * Audio segment metadata from the generated episode content
     * (`metadata.segments[]`: per-segment `duration` seconds + ASR `transcription`).
     * When present, per-item timestamps are real audio offsets (listener jump-to-item),
     * matched monotonically against segment transcriptions; otherwise `--:--`.
     */
    audioSegments?: Array<{ duration?: number; transcription?: string }>;
    /** R4. Omit to keep the default (summary on). `false` reproduces the pre-D9 body. */
    summaryParagraph?: boolean;
    /** R4. `after` moves `<style>` below the timeline; `before` is the legacy position; `omit` drops it. */
    timelineStyle?: TimelineStyle;
    seriesName?: string;
    showName?: string;
    descriptionMin?: number;
    descriptionMax?: number;
    descriptionSource?: PodcastSeoConfig['descriptionSource'];
    descriptionPattern?: string;
    /** Playback seconds for the `（约 N 分钟）` clause. Segment durations are the fallback. */
    durationSeconds?: number;
    /** Link text for the summary cross-link. Falls back to 本期完整文章. */
    surfingTitle?: string;
    refinedDescription?: string;
    summaryClauses?: string[];
}

/** Per-item 1–2-sentence briefing: `metadata.brief` first, body sentences as fallback. */
export function itemBrief(d: Doc): string {
    const meta = d.metadata ?? {};
    if (typeof meta.brief === 'string' && meta.brief.trim().length > 0) return meta.brief.trim();
    return splitSentences((d.body ?? '').trim(), { cjkOnly: true })
        .slice(0, 2)
        .join('');
}

/**
 * The 0394/0386 source label of one item: the plan's `metadata.sourceName`, else the URL host,
 * else the bare 「来源」. One convention shared by the timeline and the brief renderer.
 */
export function sourceLabelFor(doc: Doc): string {
    const metadata = doc.metadata ?? {};
    if (typeof metadata.sourceName === 'string' && metadata.sourceName.trim()) return metadata.sourceName.trim();
    try {
        return new URL(doc.sourceUri ?? '').hostname.replace(/^www\./, '');
    } catch {
        return '来源';
    }
}

/**
 * Renders the episode show-notes markdown from a plan Doc[] — plugin-owned port
 * of the workflow's inline show-notes bun -e (design L1 R6; the workflow keeps
 * only the orchestration call). Output dialect: `# title` heading, per-item
 * `## N. <title>` sections capped at the first two 。！？-terminated sentences,
 * a `[来源：<label>](<sourceUri>)` link per item, and the full-article footer.
 * Downstream HTML rendering stays with {@link renderShowNotesHtml}.
 */
export function renderShowNotesMarkdown(docs: Doc[], opts: ShowNotesRenderOptions, warnings?: string[]): string {
    const slugify = (t: string): string => {
        const s = t
            .toLowerCase()
            .replace(/[^\w\s-]/g, '')
            .trim()
            .replace(/[\s_]+/g, '-');
        return s.length > 0 ? s : 'post';
    };
    const baseUrl = opts.articleBaseUrl ?? 'https://surfing.salty.vip';
    // O(1) postPath derivation (task 0118): the published slug + locale come from
    // the real path, not from re-slugging the title. Falls back to the legacy
    // title/runDate construction when no postPath exists (surfdash failed).
    const segments = opts.articlePostPath?.split(/[\\/]/).filter((s) => s.length > 0) ?? [];
    const postSlug = segments.length >= 2 ? (segments[segments.length - 2] ?? '') : '';
    const postLocale = segments.find((s) => ['zh', 'en', 'ja'].includes(s)) ?? 'zh';
    // URL shape mirrors surfdash's localePathPrefix (surfdash/src/lib/seo.ts):
    // en is served at the site root, zh/ja carry a /<locale> prefix. A bare
    // /<locale>/posts/<slug> 404s en posts. Fallback stays zh — the podcast
    // is zh-only today.
    const localePrefix = postLocale === 'en' ? '' : `/${postLocale}`;
    const articleUrl =
        postSlug.length > 0
            ? `${baseUrl}${localePrefix}/posts/${postSlug}`
            : `${baseUrl}/zh/posts/${opts.runDate}-${slugify(opts.title)}`;
    if (opts.briefMode === true && postSlug.length === 0) {
        warn('brief mode requested but ARTICLE_POST_PATH is empty; using legacy layout', warnings);
    }
    const briefMode = opts.briefMode === true && postSlug.length > 0;
    const offsets = computeAudioOffsets(docs, opts.audioSegments);
    const lines: string[] = [`# ${opts.title}`, ''];
    const summaryOn = opts.summaryParagraph !== false;
    if (summaryOn) {
        const segmentSeconds = opts.audioSegments?.reduce((sum, segment) => sum + (segment.duration ?? 0), 0);
        const durationSeconds =
            opts.durationSeconds ?? (segmentSeconds && segmentSeconds > 0 ? segmentSeconds : undefined);
        const plan: PlanItem[] = docs.map((doc) => {
            const title = doc.title?.trim() ?? '';
            const brief = itemBrief(doc);
            return brief.length > 0 ? { title, brief } : { title };
        });
        const config: PodcastSeoConfig = {
            ...SEO_DEFAULTS,
            ...(opts.seriesName ? { seriesName: opts.seriesName } : {}),
            ...(opts.showName ? { showName: opts.showName } : {}),
            ...(opts.descriptionMin !== undefined ? { descriptionMin: opts.descriptionMin } : {}),
            ...(opts.descriptionMax !== undefined ? { descriptionMax: opts.descriptionMax } : {}),
            ...(opts.descriptionSource ? { descriptionSource: opts.descriptionSource } : {}),
            ...(opts.descriptionPattern ? { descriptionPattern: opts.descriptionPattern } : {}),
            summaryParagraph: true,
            timelineStyle: opts.timelineStyle ?? 'after',
        };
        const summary = showNotesSummaryParagraph({
            config,
            runDate: opts.runDate,
            ...(durationSeconds !== undefined ? { durationSeconds } : {}),
            plan,
            ...(opts.refinedDescription ? { refinedDescription: opts.refinedDescription } : {}),
            ...(opts.summaryClauses ? { summaryClauses: opts.summaryClauses } : {}),
            articleUrl,
            linkText: opts.surfingTitle?.trim() || '本期完整文章',
        });
        for (const line of summary.warnings) warn(line.replace(/^WARN podcast-pub:\s*/, ''), warnings);
        lines.push(summary.markdown, '');
    }
    if (briefMode) {
        // Timeline layout (2026-09-16 feedback): real audio offsets left, title + briefing
        // right, article link last — the whole brief body is one pre-built HTML block.
        lines.push(renderTimelineHtml(docs, offsets, articleUrl, opts.timelineStyle ?? 'after'), '');
    } else {
        docs.forEach((d, i) => {
            const body = (d.body ?? '').trim();
            const sentences = splitSentences(body, { cjkOnly: true }).slice(0, 2).join('');
            lines.push(
                `## ${i + 1}. ${d.title ?? `条目 ${i + 1}`}`,
                '',
                sentences,
                '',
                `[来源：${sourceLabelFor(d)}](${d.sourceUri ?? ''})`,
                '',
            );
        });
        lines.push(`详情见本期完整文章：[ ${opts.title} ](${articleUrl})`, '');
    }
    if (opts.footerNote) lines.push(opts.footerNote, '');
    return lines.join('\n');
}
